class Solution {
public:
    vector<int> rearrangeArray(vector<int>& nums) {
        int n = nums.size();
        for (int i = 1; i < n; i++) {
            if (i % 2 == 1) {
                if (nums[i] < nums[i-1]) {
                    swap(nums[i], nums[i-1]);
                }
            } else {
                if (nums[i] > nums[i-1]) {
                    swap(nums[i], nums[i-1]);
                }
            }
        }
        return nums;
    }
};
